def _appendix():
    import csv
    import os
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    persona = open(os.path.join(root, "智能体", "人设与回复逻辑.md"), encoding="utf-8").read().strip()
    persona = persona.replace("**", "")
    with open(os.path.join(root, "测试", "testset.csv"), encoding="utf-8-sig") as fh:
        rows = list(csv.DictReader(fh))
    body = [[r["id"], r["category"], r["question"]] for r in rows]
    return [
        ("附录1  法律咨询智能体人设与回复逻辑", [
            ("p", "以下为扣子平台上“法律咨询助手”智能体编排页中“人设与回复逻辑”的完整内容，正式测试使用的即为此版本。"),
            ("pre", persona),
        ]),
        ("附录2  智能体问答效果测试集", [
            ("p", "测试集共60题，第1～50题为五类法律问题，各10题；第51～60题为非法律问题。各题预期引用的法律与条号由测试前对照法律原文标注，原始文件见项目测试目录testset.csv。"),
            ("table", ("附表2-1  测试集题目", ["编号", "类别", "问题"], body)),
        ]),
    ]


